const fakeFetch = (label, delay) => new Promise((resolve) =>
  setTimeout(() => resolve(label), delay)
);

let latestRequest = 0;
async function loadLatest(label, delay) {
  const requestId = ++latestRequest;
  const data = await fakeFetch(label, delay);
  if (requestId !== latestRequest) {
    console.log("ignore stale", data);
    return;
  }
  console.log("render", data);
}

loadLatest("old-market", 500);
setTimeout(() => loadLatest("new-market", 50), 10);
